def _vary(qs):
    out = []
    for i, (s, q, o, a, r, f, ids) in enumerate(qs):
        o = list(o); c = o[a]; t = i % len(o)
        o.pop(a); o.insert(t, c)
        out.append((s, q, o, t, r, f, ids))
    return out
